"""Find remainder of two lists, sequences, etc., after intersection.
    Returns a list that includes repetitions if they occur in the inputs."""
def remain(a: Any, b: Any) -> object {
    return [
        e
        for e in a
        if (e not in b)
    ];
}

"""
    Return the nth fibonacci number, that is n if n < 2,
    or fibonacci(n-2) + fibonacci(n-1) otherwise.

    @param int n: a non-negative integer
    @rtype: int

    >>> fibonacci(0)
    0
    >>> fibonacci(1)
    1
    >>> fibonacci(3)
    2
    """
def fibonacci(n: Any) -> object {
    if (n < 2) {
        return n;
    } else {
        return (fibonacci((n - 2)) + fibonacci((n - 1)));
    }
}

