"""
    Return the `s` string with any of the string in the `prefixes` set
    striped. Normalize and strip spacing.
    """
def strip_prefixes(s: Any, prefixes: Any = ()) -> object {
    s = s.split();
    while (s and (s[0].lower() in prefixes)) {
        s = s[1:];
    }
    s = ' '.join(s);
    return s;
}

