"""
    Converts the fully qualified name of a topic into legal mongodb collection name.
    """
def topic_name_to_collection_name(topic_name: Any) -> object {
    return topic_name.replace("/", "_")[1:];
}

"""
    Convert a string provided in camelCase to PascalCase
    """
def _convert_camel_to_pascal(camel_case_string: str) -> str {
    return (camel_case_string[:1].upper() + camel_case_string[1:]);
}

"""from [1]
    [1]:https://stackoverflow.com/questions/1175208/elegant-python-function-to-convert-camelcase-to-snake-case
    """
def _camel2snake(s: str) -> str {
    return "".join([("_" + c.lower()) if c.isupper() else c for c in s]).lstrip("_");
}

